window.AUTH=window.AUTH||{};window.AUTH["21-1450"]={"d":"21-1450","id":"2022/21-1450","n":"Turkiye Halk Bankasi A.S. v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Turkiye Halk Bankasi A.S.","date":"2022-11-14","url":"https://www.supremecourt.gov/DocketPDF/21/21-1450/246391/20221114142235857_Halkbank%20Brief%20for%20Petitioner%20and%20Statutory%20Addendum.pdf","side":"pet","n":64},{"k":"respondent","label":"Brief of respondent United States","date":"2022-12-14","url":"https://www.supremecourt.gov/DocketPDF/21/21-1450/249958/20221214150140875_21-1450bsUnitedStates.pdf","side":"res","n":85},{"k":"reply","label":"Reply of petitioner Turkiye Halk Bankasi A.S.","date":"2023-01-06","url":"https://www.supremecourt.gov/DocketPDF/21/21-1450/251530/20230106112315272_Halkbank%20Reply%20Brief.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us1r13_3e04.pdf","tr":true,"items":[{"t":"case","label":"Abney v. United States","cite":"431 U.S. 651","y":1977,"id":"1976/75-6521","sc":1,"by":{"0":"13"}},{"t":"case","label":"Alfred Dunhill of London, Inc. v. Republic of Cuba","cite":"425 U.S. 682","y":1976,"id":"1974/73-1288","sc":1,"by":{"0":"44","1":"21, 29","2":"16"},"q":[{"src":"brief","b":0,"text":"a shift in policy by the executive cannot control the courts.","cite":"425 U.S. 682, 714"},{"src":"brief","b":2,"text":"a shift in policy by the executive cannot control the courts.","cite":"425 U.S. 682, 714"}]},{"t":"case","label":"Argentine Republic v. Amerada Hess Shipping Corp.","cite":"488 U.S. 428","y":1989,"id":"1988/87-1372","sc":1,"by":{"0":"passim","1":"36, 40","2":"6, 10, 18"},"q":[{"src":"brief","b":0,"text":"a foreign state was absolutely immune from the jurisdiction of the courts of another state.","cite":"488 U.S. 428"},{"src":"brief","b":0,"text":"lack of certainty as to whether the [ATS] conferred jurisdiction in suits against foreign states","cite":"488 U.S. at 436"},{"src":"brief","b":1,"text":"confer[ral of] jurisdiction on district courts,","cite":"488 U.S. 428, 434"},{"src":"brief","b":2,"text":"conferred jurisdiction in suits against foreign states.","cite":"488 U.S. 428, 436"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"Sections 1604 and 1330(a) work in tandem.","cite":"488 U. S. 428, 434"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"sole basis for obtaining jurisdiction over a foreign state in federal court.","cite":"488 U. S., at 439"}]},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"by":{"0":"26"}},{"t":"case","label":"Badgerow v. Walters","cite":"142 S. Ct. 1310","y":2022,"id":"2021/20-1143","sc":1,"by":{"0":"14, 40"}},{"t":"case","label":"Benz v. Compania Naviera Hidalgo, S.A.","cite":"353 U.S. 138","y":1957,"id":"1956/204","sc":1,"by":{"0":"21"}},{"t":"case","label":"Berizzi Bros. v. S.S. Pesaro","cite":"271 U.S. 562","y":1926,"id":"scdb/1925-172","sc":1,"by":{"0":"passim","1":"20","2":"4-5, 16"},"q":[{"src":"brief","b":0,"text":"general words … must be construed … as not intended to include","cite":"271 U.S. at 576"},{"src":"argument","who":"Ms. Blatt","text":"But, on jurisdiction, the argument in both the face of the opinion and every century, there's Berizzi Brothers, Samantar, and Kiowa Tribe, so you've got a case per century saying Schooner Exchange was a jurisdictional case."}]},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"137 S. Ct. 1312","y":2017,"id":"2016/15-423","sc":1,"by":{"0":"13, 15, 31","2":"4"}},{"t":"case","label":"Breard v. Greene","cite":"523 U.S. 371","y":1998,"id":"1997/97-8214","sc":1,"by":{"0":"23","2":"5"}},{"t":"case","label":"Compania Espanola de Navegacion Maritima, S.A. v. The Navemar","cite":"303 U.S. 68","y":1938,"id":"scdb/1937-121","sc":1,"by":{"0":"44"}},{"t":"case","label":"EEOC v. Arabian Am. Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"by":{"0":"21, 27"},"q":[{"src":"brief","b":0,"text":"Congress’ awareness of the need to make a clear statement … is amply demonstrated by the numerous occasions on which it has.","cite":"499 U.S. at 258"}]},{"t":"case","label":"F. Hoffman-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"by":{"0":"21, 22"},"q":[{"src":"brief","b":0,"text":"assume that legislators take account of the legitimate sovereign interests of other nations","cite":"542 U.S. 155, 164"}]},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"by":{"0":"23, 39"},"q":[{"src":"argument","who":"Mr. Feigin","text":"Your Honor, I think this is a case like United Air Regulatory Group or Brown & Williamson, where you have to look at the statute as a whole."}]},{"t":"case","label":"First Nat’l City Bank v. Banco Nacional de Cuba","cite":"406 U.S. 759","y":1972,"id":"1971/70-295","sc":1,"by":{"0":"17","1":"10"},"q":[{"src":"brief","b":0,"text":"sovereigns are not presumed without explicit declaration to have opened their tribunals to suits against other sovereigns.","cite":"406 U.S. 759, 762"}]},{"t":"case","label":"Fourco Glass Co. v. Transmirra Prods. Corp.","cite":"353 U.S. 222","y":1957,"id":"1956/310","sc":1,"by":{"0":"26"}},{"t":"case","label":"Franchise Tax Bd. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"by":{"0":"15"},"q":[{"src":"brief","b":0,"text":"‘set himself up for a judge of [another sovereign’s] conduct, and to oblige him to alter it.’","cite":"139 S. Ct. 1485, 1493"}]},{"t":"case","label":"Helstoski v. Meanor","cite":"442 U.S. 500","y":1979,"id":"1978/78-546","sc":1,"by":{"0":"13"}},{"t":"case","label":"Jam v. Int’l Fin. Corp.","cite":"139 S. Ct. 759","y":2019,"id":"2018/17-1011","sc":1,"by":{"0":"35","1":"39"},"q":[{"src":"brief","b":0,"text":"‘restrictive’ theory of foreign sovereign immunity.","cite":"139 S. Ct. 759, 766"}]},{"t":"case","label":"Kiobel v. Royal Dutch Petrol.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"by":{"0":"16, 20","1":"30"},"q":[{"src":"brief","b":0,"text":"fledgling Republic—struggling to receive international recognition.","cite":"569 U.S. 108, 123"},{"src":"brief","b":0,"text":"the text reaches ‘any civil action,’","cite":"569 U.S. at 118, 12425"}]},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"by":{"0":"14"}},{"t":"case","label":"Lane v. Peña","cite":"518 U.S. 187","y":1996,"id":"1995/95-365","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"narrowly in favor of the sovereign.","cite":"518 U.S. 187, 195"}]},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"0":"27"}},{"t":"case","label":"McCulloch v. Sociedad Nacional de Marineros de Honduras","cite":"372 U.S. 10","y":1963,"id":"1962/107","sc":1,"by":{"0":"18, 31"},"q":[{"src":"brief","b":0,"text":"delicate field of international relations there must be present the affirmative intention of the Congress clearly expressed.","cite":"372 U.S. 10, 21-22"},{"src":"brief","b":0,"text":"invit[e] retaliatory action from other nations.","cite":"372 U.S. at 21"}]},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"by":{"0":"32, 43"},"q":[{"src":"brief","b":0,"text":"on the assumption that the Government will use it responsibly.","cite":"579 U.S. 550, 576"},{"src":"brief","b":0,"text":"giving unintended breadth to the Acts of Congress.","cite":"579 U.S. at 569"}]},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"by":{"0":"13"},"q":[{"src":"brief","b":0,"text":"cannot be effectively vindicated after the trial has occurred.","cite":"472 U.S. 511, 525"}]},{"t":"case","label":"Murray v. Schooner Charming Betsy","cite":"6 U.S. 64","y":1804,"id":"scdb/1804-007","sc":1,"by":{"0":"10, 18, 43"},"q":[{"src":"brief","b":0,"text":"to violate the law of nations if any other possible construction remains.","cite":"6 U.S. 64, 118"}]},{"t":"case","label":"N.Y. Cent. R.R. Co. v. Chisholm","cite":"268 U.S. 29","y":1925,"id":"scdb/1924-118","sc":1,"by":{"0":"21"}},{"t":"case","label":"Nat’l City Bank of N.Y. v. Republic of China","cite":"348 U.S. 356","y":1955,"id":"scdb/1954-035","sc":1,"by":{"0":"16, 30"},"q":[{"src":"brief","b":0,"text":"[t]he freedom of a foreign sovereign from being haled into court as a defendant has impressive titledeeds.","cite":"348 U.S. 356, 358"}]},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"by":{"0":"45, 46","1":"44, 46","2":"22"},"q":[{"src":"brief","b":0,"text":"is ‘based upon’ the particular conduct that constitutes the ‘gravamen’ of the suit.","cite":"577 U.S. 27, 35"},{"src":"brief","b":1,"text":"the particular conduct that constitutes the gravamen","cite":"577 U.S. 27, 35"},{"src":"brief","b":2,"text":"the conduct constituting the gravamen of [the] suit … occurred,","cite":"577 U.S. 27, 35"}]},{"t":"case","label":"Odhiambo v. Republic of Kenya","cite":"764 F.3d 31","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/764/31/","by":{"0":"46, 47","2":"24"}},{"t":"case","label":"Opati v. Republic of Sudan","cite":"140 S. Ct. 1601","y":2020,"id":"2019/17-1268","sc":1,"by":{"0":"33","1":"21"},"q":[{"src":"brief","b":1,"text":"accept[ed] a suggestion from the Executive Branch","cite":"140 S. Ct. 1601, 1605"}]},{"t":"case","label":"Permanent Mission of India to the U.N. v. City of New York","cite":"551 U.S. 193","y":2007,"id":"2006/06-134","sc":1,"by":{"0":"34","2":"20"},"q":[{"src":"brief","b":2,"text":"codif[y] … international law at the time of the FSIA’s enactment.","cite":"551 U.S. 193, 199"}]},{"t":"case","label":"Persinger v. Islamic Republic of Iran","cite":"729 F.2d 835","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/729/835/","by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"base their sovereign immunity decisions on reciprocity.","cite":"729 F.2d 835, 841"}]},{"t":"case","label":"Republic of Argentina v. NML Cap., Ltd.","cite":"573 U.S. 134","y":2014,"id":"2013/12-842","sc":1,"by":{"0":"35","1":"33"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"any sort of immunity defense made by a foreign sovereign in an American court must stand on the Act's text. Or it must fall.","cite":"573 U. S. 134, 141–142"}]},{"t":"case","label":"Republic of Argentina v. Weltover, Inc.","cite":"504 U.S. 607","y":1992,"id":"1991/91-763","sc":1,"by":{"0":"46, 47","1":"47","2":"24"},"q":[{"src":"brief","b":0,"text":"as an immediate consequence of the defendant’s activity.","cite":"504 U.S. 607, 618"},{"src":"brief","b":1,"text":"the issue is whether the particular actions that the foreign state performs * * * are the type of actions by which a private party engages in trade and traffic or commerce.","cite":"504 U.S. 607, 614"},{"src":"brief","b":1,"text":"that the commercial character of an act is to be determined by reference to its ‘nature’ rather than its ‘purpose.’","cite":"504 U.S. at 614"},{"src":"brief","b":2,"text":"the type of action[] by which a private party engages in trade and traffic or commerce.","cite":"504 U.S. 607, 614"}]},{"t":"case","label":"Republic of Austria v. Altmann","cite":"541 U.S. 677","y":2004,"id":"2003/03-13","sc":1,"by":{"0":"28, 34, 35","2":"18"},"q":[{"src":"brief","b":0,"text":"Congress intended courts to resolve all [foreign sovereign immunity] claims ‘in conformity with the principles set forth’ in the [FSIA].","cite":"541 U.S. at 697"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"Congress established [in the FSIA] a comprehensive framework for resolving any claim of sovereign immunity.","cite":"541 U. S. 677, 699"}]},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"by":{"0":"38","2":"10"}},{"t":"case","label":"Return Mail, Inc. v. USPS","cite":"139 S. Ct. 1853","y":2019,"id":"2018/17-1594","sc":1,"by":{"0":"23"}},{"t":"case","label":"RJR Nabisco, Inc. v. Eur. Cmty.","cite":"579 U.S. 325","y":2016,"id":"2015/15-138","sc":1,"by":{"0":"38"},"q":[{"src":"brief","b":0,"text":"controversial feature[] of the U.S. legal system.","cite":"579 U.S. 325, 347 n.9"}]},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"by":{"0":"40","1":"21"},"q":[{"src":"brief","b":0,"text":"foreign states enjoyed absolute immunity from all actions.","cite":"138 S. Ct. 816, 821"},{"src":"brief","b":1,"text":"traditionally deferred to the decisions of the political branches . . . on whether to take jurisdiction over actions against foreign sovereigns.","cite":"138 S. Ct. 816, 821"}]},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"by":{"0":"35, 44","1":"passim","2":"5, 19"},"q":[{"src":"brief","b":1,"text":"diplomatic representative of the sovereign could request a ‘suggestion of immunity’ from the State Department,","cite":"560 U.S. at 311"},{"src":"brief","b":1,"text":"Congress did not mean to cover","cite":"560 U.S. at 319"},{"src":"brief","b":2,"text":"that a federal court lacked jurisdiction over","cite":"560 U.S. 305, 311"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"developed as a matter of common law.","cite":"560 U. S. 305, 311"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"nothing to suggest we should read","cite":"560 U. S., at 319"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"may still be barred by foreign sovereign immunity under the common law.","cite":"560 U. S. 305, 324"},{"src":"argument","who":"Ms. Blatt","text":"But, on jurisdiction, the argument in both the face of the opinion and every century, there's Berizzi Brothers, Samantar, and Kiowa Tribe, so you've got a case per century saying Schooner Exchange was a jurisdictional case."},{"src":"argument","who":"Mr. Feigin","text":"And -- and a couple of broader points about that are, number one, there's no dispute, and Samantar, I think, makes quite clear that states could prosecute foreign officials, and there are some instances of them having done so in history for crimes like embezzlement or rape."},{"src":"argument","who":"Mr. Feigin","text":"Putting aside foreign officials, for which there is no removal provision also, we know that from Samantar, I think, if Congress were -- actually had been thinking about this at all, that is, criminal actions, when it enacted the Foreign Sovereign Immunities Act, it would have included criminal actions in the removal provision because even -- because I think, in the world the Petitioner is envisioning, courts automatically get right whether the Foreign Sovereign Immunities Act even applies in the first place, and that would necessitate on their view dismissal of the case."}]},{"t":"case","label":"Saudi Arabia v. Nelson","cite":"507 U.S. 349","y":1993,"id":"1992/91-522","sc":1,"by":{"0":"47, 48"},"q":[{"src":"brief","b":0,"text":"only those powers that can also be exercised by private citizens, as distinct from those powers peculiar to sovereigns.","cite":"507 U.S. 349, 360"},{"src":"argument","who":"Ms. Blatt","text":"I -- I really thought it should have gone without saying that Congress has not authorized federal courts to convict Israel, Saudi Arabia, or -- or the Vatican City."}]},{"t":"case","label":"Schooner Exchange v. McFaddon","cite":"11 U.S. 116","y":1812,"id":"scdb/1812-014","sc":1,"by":{"0":"passim","2":"2, 4-5, 8-9, 12, 16-17"},"q":[{"src":"brief","b":0,"text":"descriptive of the ordinary jurisdiction of the judicial tribunals,","cite":"11 U.S. 116, 146"},{"src":"brief","b":0,"text":"in a manner not to be misunderstood.","cite":"11 U.S. 116, 137, 146"},{"src":"brief","b":2,"text":"amount to a judicial declaration of war.","cite":"11 U.S. at 126"}]},{"t":"case","label":"Sell v. United States","cite":"539 U.S. 166","y":2003,"id":"2002/02-5664","sc":1,"by":{"0":"13"},"q":[{"src":"brief","b":0,"text":"effectively unreviewable on appeal from a final judgment.","cite":"539 U.S. 166, 176"}]},{"t":"case","label":"United States v. Atilla","cite":"966 F.3d 118","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/966/118/","by":{"0":"8","1":"4"}},{"t":"case","label":"United States v. Halkbank","cite":"2020 WL 5849512","y":2020,"court":"S.D.N.Y.","by":{"0":"1"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"Well, what do you do with what Turkiye said in its amicus brief, which is that Halkbank is an arm of the state indistinguishable from the government itself?"},{"src":"argument","who":"Ms. Blatt","text":"So -- and on this bit about sort of let's just do it all under the common law, the government waived any argument that Halkbank is not an arm of the State of Turkey."}]},{"t":"case","label":"United States v. Jasin","cite":"1993 WL 259436","y":1993,"court":"E.D. Pa. July 7","by":{"0":"30","1":"25"}},{"t":"case","label":"United States v. Palmer","cite":"16 U.S. 610","y":1818,"id":"scdb/1818-038","sc":1,"by":{"0":"20"},"q":[{"src":"brief","b":0,"text":"broad enough to comprehend every human being.","cite":"16 U.S. 610, 631"}]},{"t":"case","label":"United States v. Türkiye Halk Bankasi A.Ş.","cite":"16 F.4th 336","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/16/336/","by":{"0":"1"}},{"t":"case","label":"Verlinden B.V. v. Cent. Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"by":{"0":"15, 33, 35"},"q":[{"src":"brief","b":0,"text":"comprehensively regulat[es] the amenability of foreign nations to suit in the United States.","cite":"461 U.S. at 493"},{"src":"brief","b":0,"text":"were made in two different branches, subject to a variety of factors, sometimes including diplomatic considerations.","cite":"461 U.S. at 487"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"deferred to the decisions of the political branches—in particular, those of the Executive Branch.","cite":"461 U. S. 480, 486"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"[t]he [FSIA] must be applied by the district courts in every action Page Proof Pending Publication against a foreign sovereign.","cite":"461 U. S. 480, 493"}]},{"t":"case","label":"West Virginia v. EPA","cite":"142 S. Ct. 2587","y":2022,"id":"2021/20-1530","sc":1,"by":{"0":"23"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"23"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(27)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"28","1":"13"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","by":{"0":"39"}},{"t":"usc","label":"22 U.S.C. § 8513a","url":"https://www.law.cornell.edu/uscode/text/22/8513a","subs":["(d)(2)","(d)(4)(C)"],"by":{"0":"42","1":"3, 3"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/28/1605","subs":["(a)","(a)(2)","(a)(5)","(a)(6)","(g)"],"stext":{"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","paras":[[0,"(a) A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case—"],[1,"(1) in which the foreign state has waived its immunity either explicitly or by implication, notwithstanding any withdrawal of the waiver which the foreign state may purport to effect except in accordance with the terms of the waiver;"],[1,"(2) in which the action is based upon a commercial activity carried on in the United States by the foreign state; or upon an act performed in the United States in connection with a commercial activity of the foreign state elsewhere; or upon an act outside the territory of the United States in connection with a commercial activity of the foreign state elsewhere and that act causes a direct effect in the United States;"],[1,"(3) in which rights in property taken in violation of international law are in issue and that property or any property exchanged for such property is present in the United States in connection with a commercial activity carried on in the United States by the foreign state; or that property or any property exchanged for such property is owned or operated by an agency or instrumentality of the foreign state and that agency or instrumentality is engaged in a commercial activity in the United States;"],[1,"(4) in which rights in property in the United States acquired by succession or gift or rights in immovable property situated in the United States are in issue;"],[1,"(5) not otherwise encompassed in paragraph (2) above, in which money damages are sought against a foreign state for personal injury or death, or damage to or loss of property, occurring in the United States and caused by the tortious act or omission of that foreign state or of any official or employee of that foreign state while acting within the scope of his office or employment; except this paragraph shall not apply to—"],[2,"(A) any claim based upon the exercise or performance or the failure to exercise or perform a discretionary function regardless of whether the discretion be abused, or"],[2,"(B) any claim arising out of malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights; or"],[1,"(6) in which the action is brought, either to enforce an agreement made by the foreign state with or for the benefit of a private party to submit to arbitration all or any differences which have arisen or which may arise between the parties with respect to a defined legal relationship, whether contractual or not, concerning a subject matter capable of settlement by arbitration under the laws of the United States, or to confirm an award made pursuant to such an agreement to arbitrate, if (A) the arbitration takes place or is intended to take place in the United States, (B) the agreement or award is or may be governed by a treaty or other international agreement in force for the United States calling for the recognition and enforcement of arbitral awards, (C) the underlying claim, save for the agreement to arbitrate, could have been brought in a United States court under this section or section 1607, or (D) paragraph (1) of this subsection is otherwise applicable."],[0,"(b) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any case in which a suit in admiralty is brought to enforce a maritime lien against a vessel or cargo of the foreign state, which maritime lien is based upon a commercial activity of the foreign state: Provided, That—"],[1,"(1) notice of the suit is given by delivery of a copy of the summons and of the complaint to the person, or his agent, having possession of the vessel or cargo against which the maritime lien is asserted; and if the vessel or cargo is arrested pursuant to process obtained on behalf of the party bringing the suit, the service of process of arrest shall be deemed to constitute valid delivery of such notice, but the party bringing the suit shall be liable for any damages sustained by the foreign state as a result of the arrest if the party bringing the suit had actual or constructive knowledge that the vessel or cargo of a foreign state was involved; and"],[1,"(2) notice to the foreign state of the commencement of suit as provided in section 1608 of this title is initiated within ten days either of the delivery of notice as provided in paragraph (1) of this subsection or, in the case of a party who was unaware that the vessel or cargo of a foreign state was involved, of the date such party determined the existence of the foreign state's interest."],[0,"(c) Whenever notice is delivered under subsection (b)(1), the suit to enforce a maritime lien shall thereafter proceed and shall be heard and determined according to the principles of law and rules of practice of suits in rem whenever it appears that, had the vessel been privately owned and possessed, a suit in rem might have been maintained. A decree against the foreign state may include costs of the suit and, if the decree is for a money judgment, interest as ordered by the court, except that the court may not award judgment against the foreign state in an amount greater than the value of the vessel or cargo upon which the maritime lien arose. Such value shall be determined as of the time notice is served under subsection (b)(1). Decrees shall be subject to appeal and revision as provided in other cases of admiralty and maritime jurisdiction. Nothing shall preclude the plaintiff in any proper case from seeking relief in personam in the same action brought to enforce a maritime lien as provided in this section."],[0,"(d) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any action brought to foreclose a preferred mortgage, as defined in section 31301 of title 46. Such action shall be brought, heard, and determined in accordance with the provisions of chapter 313 of title 46 and in accordance with the principles of law and rules of practice of suits in rem, whenever it appears that had the vessel been privately owned and possessed a suit in rem might have been maintained."],[0,"[(e), (f) Repealed. Pub. L. 110–181, div. A, title X, §1083(b)(1)(B), Jan. 28, 2008, 122 Stat. 341.]"],[0,"(g) Limitation on Discovery.—"],[1,"(1) In general.—(A) Subject to paragraph (2), if an action is filed that would otherwise be barred by section 1604, but for section 1605A or section 1605B, the court, upon request of the Attorney General, shall stay any request, demand, or order for discovery on the United States that the Attorney General certifies would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action, until such time as the Attorney General advises the court that such request, demand, or order will no longer so interfere."],[1,"(B) A stay under this paragraph shall be in effect during the 12-month period beginning on the date on which the court issues the order to stay discovery. The court shall renew the order to stay discovery for additional 12-month periods upon motion by the United States if the Attorney General certifies that discovery would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action."],[1,"(2) Sunset.—(A) Subject to subparagraph (B), no stay shall be granted or continued in effect under paragraph (1) after the date that is 10 years after the date on which the incident that gave rise to the cause of action occurred."],[1,"(B) After the period referred to in subparagraph (A), the court, upon request of the Attorney General, may stay any request, demand, or order for discovery on the United States that the court finds a substantial likelihood would—"],[2,"(i) create a serious threat of death or serious bodily injury to any person;"],[2,"(ii) adversely affect the ability of the United States to work in cooperation with foreign and international law enforcement agencies in investigating violations of United States law; or"],[2,"(iii) obstruct the criminal case related to the incident that gave rise to the cause of action or undermine the potential for a conviction in such case."],[1,"(3) Evaluation of evidence.—The court's evaluation of any request for a stay under this subsection filed by the Attorney General shall be conducted ex parte and in camera."],[1,"(4) Bar on motions to dismiss.—A stay of discovery under this subsection shall constitute a bar to the granting of a motion to dismiss under rules 12(b)(6) and 56 of the Federal Rules of Civil Procedure."],[1,"(5) Construction.—Nothing in this subsection shall prevent the United States from seeking protective orders or asserting privileges ordinarily available to the United States."],[0,"(h) Jurisdictional Immunity for Certain Art Exhibition Activities.—"],[1,"(1) In general.—If—"],[2,"(A) a work is imported into the United States from any foreign state pursuant to an agreement that provides for the temporary exhibition or display of such work entered into between a foreign state that is the owner or custodian of such work and the United States or one or more cultural or educational institutions within the United States;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"36, 42, 43, 5, 10, 42, 43, 46, passim, 43, 44, 34"},"q":[{"src":"brief","b":0,"text":"cause[] a direct effect in the United States.","cite":"28 U.S.C. § 1605(a)(2)"},{"src":"brief","b":1,"text":"[g]eneral exceptions to the jurisdictional immunity of a foreign state.","cite":"28 U.S.C. 1605"},{"src":"brief","b":1,"text":"an act outside the territory of the United States in connection with a commercial activity of the foreign state elsewhere and that act causes a direct effect in the United States.","cite":"28 U.S.C. 1605(a)(2)"},{"src":"argument","who":"Ms. Blatt","text":"Finally, Section 1605's commercial activities exception cannot apply in criminal cases. Section 1330 grants jurisdiction for the exceptions in civil cases only."}]},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"0":"23"}},{"t":"usc","label":"45 U.S.C. § 51","url":"https://www.law.cornell.edu/uscode/text/45/51","by":{"0":"21"}},{"t":"law","label":"Pub. L. No. 80-772","by":{"0":"26"}},{"t":"law","label":"Foreign Sovereign Immunities Act, Pub. L. No. 94-583","url":"https://www.govinfo.gov/link/statute/90/2891","by":{"0":"passim"}},{"t":"reg","label":"31 C.F.R. pt. 501","url":"https://www.ecfr.gov/current/title-31/part-501","by":{"0":"42","2":"11"}},{"t":"rule","label":"Fed. R. Crim. P. 4.1","url":"https://www.law.cornell.edu/rules/frcrmp/rule_4.1","by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"by any … means that gives notice.","cite":"Fed. R. Crim. P. 4.1(c)(3)(D)(ii)"}]},{"t":"rule","label":"Fed. R. Crim. P. 32.2","url":"https://www.law.cornell.edu/rules/frcrmp/rule_32.2","by":{"0":"38"}},{"t":"case","label":"American Ins. Ass’n v. Garamendi","cite":"539 U.S. 396","y":2003,"id":"2002/02-722","sc":1,"by":{"1":"31"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"578 U.S. 212","y":2016,"id":"2015/14-770","sc":1,"by":{"1":"22, 30"}},{"t":"case","label":"Cassirer v. Thyssen-Bornemisza Collection Found.","cite":"142 S. Ct. 1502","y":2022,"id":"2021/20-1566","sc":1,"by":{"1":"9, 33, 35"},"q":[{"src":"brief","b":1,"text":"lays down a baseline principle of foreign sovereign immunity from civil actions.","cite":"142 S. Ct. 1502, 1508"},{"src":"brief","b":1,"text":"lists a series of exceptions from that principle.","cite":"142 S. Ct. 1502, 1508"}]},{"t":"case","label":"Chicago & S. Air Lines, Inc. v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"1":"31"}},{"t":"case","label":"Chisom v. Roemer","cite":"501 U.S. 380","y":1991,"id":"1990/90-757","sc":1,"by":{"1":"39"},"q":[{"src":"brief","b":1,"text":"Congress’ silence in this regard can be likened to the dog that did not bark.","cite":"501 U.S. 380, 396 n.23"}]},{"t":"case","label":"Coale v. Société Coop. Suisse des Charbons","cite":"21 F.2d 180","y":1921,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.2d/21/180/","by":{"1":"18","2":"15"}},{"t":"case","label":"Cook Cnty. v. United States ex rel. Chandler","cite":"538 U.S. 119","y":2003,"id":"2002/01-1572","sc":1,"by":{"1":"14"}},{"t":"case","label":"Devengoechea v. Bolivarian Republic of Venez.","cite":"889 F.3d 1213","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/889/1213/","by":{"1":"48"}},{"t":"case","label":"First Nat’l City Bank v. Banco Para El Comercio Exterior de Cuba","cite":"462 U.S. 611","y":1983,"id":"1982/81-984","sc":1,"by":{"1":"16, 24","2":"12-13"},"q":[{"src":"brief","b":1,"text":"government instrumentalities established as juridical entities distinct and independent from their sovereign should normally be treated as such.","cite":"462 U.S. 611, 626-627"}]},{"t":"case","label":"Gould Coupler Co. v. U.S. Shipping Bd. Emergency Fleet Corp.","cite":"261 F. 716","y":1919,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./261/716/","by":{"1":"17","2":"15"},"q":[{"src":"brief","b":1,"text":"that, in entering upon industrial and commercial ventures, the governmental agencies used should, whenever it can fairly be drawn from the statutes, be subject to the same liabilities and to the same tribunals as other persons or corporations similarly employed.","cite":"261 F. 716, 718"}]},{"t":"case","label":"Graham Cnty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"[c]ourts have a duty to construe statutes, not isolated provisions.","cite":"559 U.S. 280, 290"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"duty to construe statutes, not isolated provisions.","cite":"559 U. S. 280, 290"}]},{"t":"case","label":"Lockerty v. Phillips","cite":"319 U.S. 182","y":1943,"id":"scdb/1942-149","sc":1,"by":{"1":"15"}},{"t":"case","label":"Merlini v. Canada","cite":"926 F.3d 21","y":2019,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/926/21/","by":{"1":"46"}},{"t":"case","label":"Molina v. Comision Reguladora del Mercado de Henequen","cite":"103 A. 397","y":1918,"court":"N.J.","url":"https://www.courtlistener.com/c/A./103/397/","by":{"1":"18","2":"15"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"by":{"1":"14, 36"}},{"t":"case","label":"Munaf v. Geren","cite":"553 U.S. 674","y":2008,"id":"2007/06-1666","sc":1,"by":{"1":"22, 23, 30","2":"5"},"q":[{"src":"brief","b":1,"text":"[A]s Chief Justice Marshall explained in the Schooner Exchange, ‘exemptions from territorial jurisdiction . . . must be derived from the consent of the sovereign of the territory’ and are ‘rather questions of policy than of law, that they are for diplomatic, rather than legal discussion.’","cite":"553 U.S. 674, 701"}]},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"by":{"1":"12"},"q":[{"src":"brief","b":1,"text":"inquiry begins with the statutory text.","cite":"138 S. Ct. 617, 631"}]},{"t":"case","label":"New York Cent. & Hudson River R.R. v. United States","cite":"212 U.S. 481","y":1909,"id":"scdb/1908-096","sc":1,"by":{"1":"24"}},{"t":"case","label":"Pasquantino v. United States","cite":"544 U.S. 349","y":2005,"id":"2004/03-725","sc":1,"by":{"1":"23"},"q":[{"src":"brief","b":1,"text":"assess[] th[e] prosecution’s impact on this Nation’s relationship with","cite":"544 U.S. 349, 369"}]},{"t":"case","label":"Petersen Energía Inversora S.A.U. v. Argentine Republic","cite":"895 F.3d 194","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/895/194/","by":{"1":"47"}},{"t":"case","label":"Republic of Iraq v. Beaty","cite":"556 U.S. 848","y":2009,"id":"2008/07-1090","sc":1,"by":{"1":"22, 37"},"q":[{"src":"brief","b":1,"text":"the case-by-case prerogative of the Executive Branch.","cite":"556 U.S. 848, 857"},{"src":"brief","b":1,"text":"the case-by-case prerogative of the Executive Branch,","cite":"556 U.S. at 857"}]},{"t":"case","label":"Republic of Mex. v. Hoffman","cite":"324 U.S. 30","y":1945,"id":"scdb/1944-078","sc":1,"by":{"1":"8, 15, 19, 20, 23","2":"12"},"q":[{"src":"brief","b":1,"text":"allow an immunity on new grounds which the government has not seen fit to recognize.","cite":"324 U.S. 30, 35"},{"src":"brief","b":1,"text":"rule of substantive law governing the exercise of * * * jurisdiction.","cite":"324 U.S. 30, 36"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"rule of substantive law governing the exercise of the jurisdiction of the courts,","cite":"324 U. S. 30, 36"}]},{"t":"case","label":"Rodriguez v. Pan Am. Health Org.","cite":"29 F.4th 706","y":2022,"court":"D.C.Cir.","url":"https://www.courtlistener.com/c/F.4th/29/706/","by":{"1":"45, 48"}},{"t":"case","label":"SAS Inst. Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"by":{"1":"42"},"q":[{"src":"brief","b":1,"text":"word ‘any’ naturally carries ‘an expansive meaning.’","cite":"138 S. Ct. 1348, 1354"}]},{"t":"case","label":"Salinas v. United States","cite":"522 U.S. 52","y":1997,"id":"1997/96-738","sc":1,"by":{"1":"49"}},{"t":"case","label":"Sloan Shipyards Corp. v. United States Shipping Bd. Emergency Fleet Corp.","cite":"258 U.S. 549","y":1922,"id":"scdb/1921-112","sc":1,"by":{"1":"7, 17","2":"15"},"q":[{"src":"brief","b":1,"text":"a very dangerous departure from one of the first principles of our system of law.","cite":"258 U.S. 549, 566"}]},{"t":"case","label":"United States v. Armstrong","cite":"517 U.S. 456","y":1996,"id":"1995/95-157","sc":1,"by":{"1":"31, 36"},"q":[{"src":"brief","b":1,"text":"Attorney General and United States Attorneys retain broad discretion to enforce the Nation’s criminal laws.","cite":"517 U.S. at 464"}]},{"t":"case","label":"United States v. Batchelder","cite":"442 U.S. 114","y":1979,"id":"1978/78-776","sc":1,"by":{"1":"10"}},{"t":"case","label":"United States v. Bowman","cite":"260 U.S. 94","y":1922,"id":"scdb/1922-015","sc":1,"by":{"1":"29"}},{"t":"case","label":"United States v. Deutsches Kalisyndikat Gesellschaft","cite":"31 F.2d 199","y":1929,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.2d/31/199/","by":{"1":"24, 25","2":"8"}},{"t":"case","label":"United States v. Fokker Servs. B.V.","cite":"818 F.3d 733","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/818/733/","by":{"1":"36"}},{"t":"case","label":"United States v. Ho","cite":"2016 WL 5875005","y":2016,"court":"E.D. Tenn. Oct. 7","by":{"1":"26"}},{"t":"case","label":"United States v. Noriega","cite":"117 F.3d 1206","y":1997,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/117/1206/","by":{"1":"23"}},{"t":"case","label":"United States v. Ravara","cite":"27 F. Cas. 714","y":1794,"court":"C.C.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Cas./27/714/","by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"that the offence was indictable, and that the defendant was not privileged from prosecution in virtue of his consular appointment.","cite":"27 F. Cas. 714, 715"}]},{"t":"case","label":"United States v. Wilder","cite":"28 F. Cas. 601","y":1838,"court":"C.C.D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./28/601/","by":{"1":"19","2":"16"},"q":[{"src":"brief","b":1,"text":"be applicable to the common property of the sovereign of a commercial character, or engaged in the common business of commerce.","cite":"28 F. Cas. 601, 603"}]},{"t":"case","label":"United States v. Williams","cite":"514 U.S. 527","y":1995,"id":"1994/94-395","sc":1,"by":{"1":"43"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"1":"6"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"13"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","by":{"1":"40"}},{"t":"usc","label":"11 U.S.C. § 101et","url":"https://www.law.cornell.edu/uscode/text/11/101et","by":{"1":"13"}},{"t":"usc","label":"11 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/11/106","subs":["(a)"],"by":{"1":"13"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","subs":["(a)"],"stext":{"head":"§1330. Actions against foreign states","paras":[[0,"(a) The district courts shall have original jurisdiction without regard to amount in controversy of any nonjury civil action against a foreign state as defined in section 1603(a) of this title as to any claim for relief in personam with respect to which the foreign state is not entitled to immunity either under sections 1605–1607 of this title or under any applicable international agreement."],[0,"(b) Personal jurisdiction over a foreign state shall exist as to every claim for relief over which the district courts have jurisdiction under subsection (a) where service has been made under section 1608 of this title."],[0,"(c) For purposes of subsection (b), an appearance by a foreign state does not confer personal jurisdiction with respect to any claim for relief not arising out of any transaction or occurrence enumerated in sections 1605–1607 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1330?type=usc&year=mostrecent&link-type=html"},"by":{"1":"4, passim","2":"17-18, 20"},"q":[{"src":"brief","b":1,"text":"any nonjury civil action * * * as to any claim for relief in personam with respect to which a foreign state is not entitled to immunity.","cite":"28 U.S.C. 1330(a)"},{"src":"argument","who":"Ms. Blatt","text":"Section 1330 grants jurisdiction for the exceptions in civil cases only. And a contrary reading produces two radically implausible and dangerous results."},{"src":"argument","who":"Ms. Blatt","text":"Well, no, our -- our main argument is that the Section 1604, with -- with -- with -- bars any jurisdiction, speaks more broadly than Section 1330, which opens up only civil jurisdiction."},{"src":"argument","who":"Ms. Blatt","text":"The very first prosit -- provision of the Foreign Sovereign Immunities Act is Section 1330, and it says there's civil jurisdiction for these exceptions."}]},{"t":"usc","label":"28 U.S.C. § 1603","url":"https://www.law.cornell.edu/uscode/text/28/1603","subs":["(b)(2)","(d)","(e)"],"stext":{"head":"§1603. Definitions","paras":[[0,"For purposes of this chapter—"],[1,"(a) A \"foreign state\", except as used in section 1608 of this title, includes a political subdivision of a foreign state or an agency or instrumentality of a foreign state as defined in subsection (b)."],[1,"(b) An \"agency or instrumentality of a foreign state\" means any entity—"],[2,"(1) which is a separate legal person, corporate or otherwise, and"],[2,"(2) which is an organ of a foreign state or political subdivision thereof, or a majority of whose shares or other ownership interest is owned by a foreign state or political subdivision thereof, and"],[2,"(3) which is neither a citizen of a State of the United States as defined in section 1332 (c) and (e) of this title, nor created under the laws of any third country."],[1,"(c) The \"United States\" includes all territory and waters, continental or insular, subject to the jurisdiction of the United States."],[1,"(d) A \"commercial activity\" means either a regular course of commercial conduct or a particular commercial transaction or act. The commercial character of an activity shall be determined by reference to the nature of the course of conduct or particular transaction or act, rather than by reference to its purpose."],[1,"(e) A \"commercial activity carried on in the United States by a foreign state\" means commercial activity carried on by such state and having substantial contact with the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1603?type=usc&year=mostrecent&link-type=html"},"by":{"1":"27, 46, 48, 10, 48"},"q":[{"src":"brief","b":1,"text":"agency or instrumentality of a foreign state","cite":"28 U.S.C. 1603(b)(2)"},{"src":"brief","b":1,"text":"The commercial character of an activity [is] determined by reference to the nature of the course of conduct or particular transaction or act, rather than by reference to its purpose.","cite":"28 U.S.C. 1603(d)"}]},{"t":"usc","label":"28 U.S.C. § 1604","url":"https://www.law.cornell.edu/uscode/text/28/1604","stext":{"head":"§1604. Immunity of a foreign state from jurisdiction","paras":[[0,"Subject to existing international agreements to which the United States is a party at the time of enactment of this Act a foreign state shall be immune from the jurisdiction of the courts of the United States and of the States except as provided in sections 1605 to 1607 of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1604?type=usc&year=mostrecent&link-type=html"},"by":{"1":"15, 35, 42"},"q":[{"src":"brief","b":1,"text":"foreign state shall be immune from the jurisdiction of the courts of the United States and of the States except as provided in sections 1605 to 1607.","cite":"28 U.S.C. 1604"},{"src":"brief","b":1,"text":"except as provided in sections 1605 to 1607.","cite":"28 U.S.C. 1604"},{"src":"argument","who":"Ms. Blatt","text":"Section 1604 provides that foreign state shall be immune from the jurisdiction of federal and state courts. Reading the word \"civil\" into that text would mean Congress created special guardrails in civil cases but threw sovereigns to the wolves in criminal cases."},{"src":"argument","who":"Ms. Blatt","text":"And if this Court rejects that, we have another argument saying, well, the FSIA on its face in Section 1604 would cancel out any criminal jurisdiction that might otherwise exist under Title 18."},{"src":"argument","who":"Ms. Blatt","text":"Well, no, our -- our main argument is that the Section 1604, with -- with -- with -- bars any jurisdiction, speaks more broadly than Section 1330, which opens up only civil jurisdiction."}]},{"t":"usc","label":"28 U.S.C. § 1606","url":"https://www.law.cornell.edu/uscode/text/28/1606","by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"shall not be liable for punitive damages.","cite":"28 U.S.C. 1606"},{"src":"argument","who":"Mr. Feigin","text":"That's why the FSIA itself in Section 1606 allows punitive damages against government-owned corporations but not against the sovereign itself because the actions of the corporations can be wrongful, even if we don't think the actions of the sovereign qua sovereign can."}]},{"t":"usc","label":"28 U.S.C. § 1608","url":"https://www.law.cornell.edu/uscode/text/28/1608","subs":["(a)(1)","(d)"],"by":{"1":"9, 35, 35"},"q":[{"src":"brief","b":1,"text":"answer or other responsive pleading to the complaint,","cite":"28 U.S.C. 1608(d)"}]},{"t":"usc","label":"50 U.S.C. § 1701","url":"https://www.law.cornell.edu/uscode/text/50/1701","by":{"1":"2"}},{"t":"usc","label":"50 U.S.C. § 1705","url":"https://www.law.cornell.edu/uscode/text/50/1705","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"1":"2"},"q":[{"src":"argument","who":"Ms. Blatt","text":"Yeah, my reading under the section 2 is you're going to give them the deference that they are due in foreign policy if Congress hasn't spoken."}]},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/18/1344","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 1956","url":"https://www.law.cornell.edu/uscode/text/18/1956","subs":["(a)(2)(A)","(h)"],"by":{"1":"2, 2"}},{"t":"usc","label":"18 U.S.C. § 3231","url":"https://www.law.cornell.edu/uscode/text/18/3231","stext":{"head":"§3231. District courts","paras":[[0,"The district courts of the United States shall have original jurisdiction, exclusive of the courts of the States, of all offenses against the laws of the United States."],[0,"Nothing in this title shall be held to take away or impair the jurisdiction of the courts of the several States under the laws thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3231?type=usc&year=mostrecent&link-type=html"},"by":{"1":"passim","2":"2-5, 7, 13, 18, 20"},"q":[{"src":"brief","b":1,"text":"plainly has subject matter jurisdiction over the federal criminal prosecution","cite":"18 U.S.C. 3231"},{"src":"brief","b":1,"text":"district courts of the United States shall have original jurisdiction * * * of all offenses against the laws of the United States.","cite":"18 U.S.C. 3231"},{"src":"brief","b":2,"text":"is a demeaning move against Türkiye’s dignity.","cite":"18 U.S.C. § 3231"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"offenses against the laws of the United States.","cite":"18 U. S. C. § 3231"},{"src":"argument","who":"Ms. Blatt","text":"It is outlandish to think that Section 3231 authorizes federal courts to convict Spain. The U.S. does not dispute that criminal trials against sovereigns were unthinkable in 1789, would violate international law today, are unprecedented anywhere, and would risk retaliation."}]},{"t":"usc","label":"28 U.S.C. § 1333","url":"https://www.law.cornell.edu/uscode/text/28/1333","by":{"1":"40"}},{"t":"usc","label":"28 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/28/1391","subs":["(f)"],"by":{"1":"9, 34"}},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(d)"],"by":{"1":"9, 35"}},{"t":"case","label":"Bank of the U.S. v. Planters’ Bank of Ga.","cite":"22 U.S. 904","y":1824,"id":"scdb/1824-035","sc":1,"by":{"2":"15"}},{"t":"case","label":"Fed. Land Bank of St. Louis v. Priddy","cite":"295 U.S. 229","y":1935,"id":"scdb/1934-121","sc":1,"by":{"2":"12"}},{"t":"case","label":"Federal Republic of Germany v. Philipp","cite":"141 S. Ct. 703","y":2021,"id":"2020/19-351","sc":1,"by":{"2":"10"}},{"t":"case","label":"FG Hemisphere Assocs. v. Democratic Republic of Congo","cite":"637 F.3d 373","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/637/373/","by":{"2":"11"},"q":[{"src":"brief","b":2,"text":"the dignity of the foreign State.","cite":"637 F.3d 373"}]},{"t":"case","label":"FHA v. Burr","cite":"309 U.S. 242","y":1940,"id":"scdb/1939-089","sc":1,"by":{"2":"12"}},{"t":"case","label":"Garcia v. San Antonio Metro. Transit Auth.","cite":"469 U.S. 528","y":1985,"id":"1983/82-1913","sc":1,"by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"unorthodox or unnecessary [to] anyone else.","cite":"469 U.S. 528, 546"}]},{"t":"case","label":"Glass v. Sloop Betsey","cite":"3 U.S. 6","y":1794,"id":"scdb/1794-002","sc":1,"by":{"2":"6"}},{"t":"case","label":"Kiowa Tribe v. Mfg. Techs.","cite":"523 U.S. 751","y":1998,"id":"1997/96-1037","sc":1,"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"came to be regarded as extending virtually absolute immunity to foreign sovereigns,","cite":"523 U.S. 751, 759"},{"src":"argument","who":"Ms. Blatt","text":"But, on jurisdiction, the argument in both the face of the opinion and every century, there's Berizzi Brothers, Samantar, and Kiowa Tribe, so you've got a case per century saying Schooner Exchange was a jurisdictional case."}]},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"by":{"2":"12, 15"},"q":[{"src":"brief","b":2,"text":"corporations are part of the Government.","cite":"513 U.S. 374, 395"},{"src":"argument","who":"Ms. Blatt","text":"But cases like, you know, Lebron/Amtrak, Thacker, FDIC versus Meyer, you've had a million cases involving federal instrumentalities, and it's always been enough that Congress designated it as such, and it is a sovereign but for the \"sue and be sued\" clause, which waives the immunity it would otherwise have."}]},{"t":"case","label":"Nathan v. Virginia","cite":"1 U.S. 77","y":1781,"court":"Pa. C.P.","url":"https://supreme.justia.com/cases/federal/us/1/77/","sc":1,"by":{"2":"16"}},{"t":"case","label":"Republic of Argentina v. NML Cap.","cite":"573 U.S. Br. 134","y":2014,"url":"https://www.courtlistener.com/c/U.S.%20Br./573/134/","by":{"2":"10"}},{"t":"case","label":"SACE S.p.A. v. Republic of Paraguay","cite":"243 F. Supp. 3d 21","y":2017,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/243/21/","by":{"2":"23"}},{"t":"case","label":"Thacker v. TVA","cite":"139 S. Ct. 1435","y":2019,"id":"2018/17-1201","sc":1,"by":{"2":"12, 14"},"q":[{"src":"argument","who":"Ms. Blatt","text":"But cases like, you know, Lebron/Amtrak, Thacker, FDIC versus Meyer, you've had a million cases involving federal instrumentalities, and it's always been enough that Congress designated it as such, and it is a sovereign but for the \"sue and be sued\" clause, which waives the immunity it would otherwise have."}]},{"t":"case","label":"United States v. Greene","cite":"26 F. Cas. 33","y":1827,"court":"D. Me.","url":"https://www.courtlistener.com/c/F.%20Cas./26/33/","by":{"2":"4"},"q":[{"src":"brief","b":2,"text":"embrace the sovereign power or government, unless expressly named or included by necessary implication.","cite":"26 F. Cas. 33, 34"}]},{"t":"case","label":"United States v. Pangang Grp.","cite":"6 F.4th 946","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/946/","by":{"2":"8"},"q":[{"src":"argument","who":"Mr. Feigin","text":"You see some of them in the Pangang litigation, where we are prosecuting a Chinese government-owned corporation for acts of economic espionage."},{"src":"argument","who":"Mr. Feigin","text":"If you look at a couple of our recent prosecutions, the Pangang one I referred to earlier is a Chinese-owned corporation that is engaging in economic espionage."}]},{"t":"case","label":"W.S. Kirkpatrick & Co. v. Env’t Tectonics Corp.","cite":"493 U.S. 400","y":1990,"id":"1989/87-2066","sc":1,"by":{"2":"17"},"q":[{"src":"brief","b":2,"text":"to decide cases and controversies properly presented to them.","cite":"493 U.S. 400, 409"}]},{"t":"case","label":"Will v. Mich. Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"by":{"2":"4"}},{"t":"case","label":"Zivotofsky v. Kerry","cite":"576 U.S. 1","y":2015,"id":"2014/13-628","sc":1,"by":{"2":"9"},"q":[{"src":"brief","b":2,"text":"[t]he Executive is not free from the ordinary controls and checks of Congress merely because foreign affairs are at issue.","cite":"576 U.S. 1, 21"}]},{"t":"usc","label":"12 U.S.C. § 635","url":"https://www.law.cornell.edu/uscode/text/12/635","by":{"2":"13"}},{"t":"usc","label":"22 U.S.C. § 9612","url":"https://www.law.cornell.edu/uscode/text/22/9612","by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"facilitate[s] the participation of private sector capital and skills in the economic development of less developed countries.","cite":"22 U.S.C. § 9612(b)"}]},{"t":"usc","label":"31 U.S.C. § 9101","url":"https://www.law.cornell.edu/uscode/text/31/9101","by":{"2":"13"}}]};